def icon(name, cls="ico"):
    """文字の横に置く飾りのアイコン（読み上げには出さない）。名前が無ければ止まる。"""
    return (f'<svg class="{cls}" viewBox="0 -960 960 960" aria-hidden="true" focusable="false">'
            f'<path d="{PATHS[name]}"/></svg>')
